import { useEffect, useState } from 'react';
import type { ClientPluginContext, UiRuntime, ViewProps } from '@aork/sdk/client';
import type { PermissionInteraction } from '@aork/contracts/interaction';
function usePermissions(runtime:UiRuntime){const [values,setValues]=useState<PermissionInteraction[]>([]);const [sessionId,setSessionId]=useState(()=>new URLSearchParams(location.hash.slice(1)).get('session'));const [error,setError]=useState('');useEffect(()=>{const update=()=>setSessionId(new URLSearchParams(location.hash.slice(1)).get('session'));addEventListener('hashchange',update);return()=>removeEventListener('hashchange',update);},[]);useEffect(()=>{if(!sessionId)return;let active=true;const stop=runtime.observeSnapshot<{interactions:PermissionInteraction[]}>('interactions.history',{sessionId}, {next(value){if(active){setValues(value.interactions);setError('');}},error(failure){if(active)setError(failure.message);}},{owners:['interactions']});return()=>{active=false;void stop();};},[runtime,sessionId]);return {values:values.filter(value=>value.sessionId===sessionId),error};}
function Detail({runtime}:ViewProps){return <section aria-label="公开组合会话"><h2>公开权限工作台</h2>{runtime.renderView('aork.sessions.messages@1')}{runtime.renderView('aork.interactions.cards@1')}{runtime.renderView('aork.sessions.composer@1')}</section>;}
function Cards({runtime}:ViewProps){const {values,error}=usePermissions(runtime);return <section aria-label="独立权限卡片"><h3>独立权限卡片</h3>{values.map(value=><article key={value.id}><strong>{value.title}</strong><p>来源 Agent · {value.runId} · {value.generation}</p><p role="status">{value.state}</p></article>)}{runtime.renderView('aork.interactions.permission@1')}{error&&<p role="alert">{error}</p>}</section>;}
function Permission({runtime}:ViewProps){const {values,error}=usePermissions(runtime);const [failure,setFailure]=useState('');const [busy,setBusy]=useState(false);const value=values.find(value=>value.state==='pending');return <form aria-label="独立审批表单" onSubmit={event=>event.preventDefault()}>{value?.options.map(option=><button key={option.optionId} disabled={busy||Boolean(error)} onClick={async()=>{if(busy)return;setBusy(true);setFailure('');try{await runtime.command('interactions.respond',{interactionId:value.id,optionId:option.optionId},crypto.randomUUID());}catch(caught){setFailure(caught instanceof Error?caught.message:'Response rejected');}finally{setBusy(false);}}}>独立选择 {option.name}</button>)}{(error||failure)&&<p role="alert">{error||failure}</p>}</form>;}
function PendingCards({runtime}:ViewProps){const [values,setValues]=useState<PermissionInteraction[]>([]);const sessionId=new URLSearchParams(location.hash.slice(1)).get('session');useEffect(()=>{if(!sessionId)return;return runtime.observeSnapshot<{pending:PermissionInteraction[]}>('interactions.pending',{sessionId},{next(value){setValues(value.pending);}},{owners:['interactions']});},[runtime,sessionId]);return <section aria-label="独立待处理权限卡片">{values.map(value=><article key={value.id}><strong>{value.title}</strong><p role="status">{value.state}</p></article>)}{runtime.renderView('aork.interactions.permission@1')}</section>;}
export function activate(context:ClientPluginContext){context.registerView('pending-cards',PendingCards);context.registerView('detail',Detail);context.registerView('cards',Cards);context.registerView('permission',Permission);}
